347	static int
348	adjust_gain(uint32_t newfreq)
349	{
350	  int new_order = newfreq / FREQ_HARMONICS;
351	  int old_order = si5351_get_frequency() / FREQ_HARMONICS;
352	  if (new_order != old_order) {
353	    tlv320aic3204_set_gain(gain_table[new_order], gain_table[new_order]);
354	    return DELAY_GAIN_CHANGE;
355	  }
356	  return 0;
357	}
358	
359	int set_frequency(uint32_t freq)
360	{
361	  int delay = adjust_gain(freq);
362	  int8_t ds = drive_strength;
363	  if (ds == DRIVE_STRENGTH_AUTO) {
364	    ds = freq > FREQ_HARMONICS ? SI5351_CLK_DRIVE_STRENGTH_8MA : SI5351_CLK_DRIVE_STRENGTH_2MA;
365	  }
366	  delay += si5351_set_frequency(freq, ds);
