  for (; i < sweep_points; i++) {
    // fill cal_data at tail of src
    for (eterm = 0; eterm < 5; eterm++) {
      cal_data[eterm][i][0] = src->_cal_data[eterm][src->_sweep_points-1][0];
      cal_data[eterm][i][1] = src->_cal_data[eterm][src->_sweep_points-1][1];
    }
